	destroy_rec(n->right, value_free);
	node_release(n, value_free);
}

void rb_destroy(rbtree_t *t)
{
	if (t == NULL)
		return; /* NULL-safe per include/rbtree.h */

	destroy_rec(t->root, t->value_free);
	free(t);
}

