#include <string.h>

static int check_failed = 0;
#define CHECK(cond, msg) do { if (!(cond)) { printf("FAIL: %s\n", msg); check_failed = 1; } } while (0)

/* --- rb_foreach in-order correctness (never actually tested before) --- */
static char foreach_out[4096];
static void collect(const char *key, void *value, void *ctx)
{
	(void)value;
	strcat((char *)ctx, key);
	strcat((char *)ctx, ",");
}

static void test_foreach(void)
{
	printf("== rb_foreach in-order ==\n");
	rbtree_t *t = rb_create(NULL);
	const char *keys[] = {"m","c","x","a","g","p","z"};
	for (int i = 0; i < 7; i++) rb_insert(t, keys[i], NULL);
	foreach_out[0] = '\0';
	rb_foreach(t, collect, foreach_out);
	printf("  got: %s\n", foreach_out);
	CHECK(strcmp(foreach_out, "a,c,g,m,p,x,z,") == 0, "rb_foreach did not visit in sorted order");
	rb_destroy(t);
