/* --- overwrite path: known-broken, document exactly how --- */
static void test_overwrite(void)
{
	printf("== rb_insert overwrite (known gap) ==\n");
	rbtree_t *t = rb_create(NULL);
	static char v1[] = "first", v2[] = "second";
	int rc1 = rb_insert(t, "dup", v1);
	int rc2 = rb_insert(t, "dup", v2);
	void *found = rb_find(t, "dup");
	printf("  rc1=%d rc2=%d found=%s size=%zu\n", rc1, rc2,
	       found ? (const char *)found : "(null)", rb_size(t));
	printf("  per Appendix A: rc2 should be 0, found should be \"second\", size should be 1\n");
	rb_destroy(t);
}

/* --- edge cases: empty tree, single node --- */
static void test_edges(void)
{
	printf("== edge cases ==\n");
	rbtree_t *t = rb_create(NULL);
	CHECK(rb_find(t, "x") == NULL, "find on empty tree should be NULL");
	CHECK(rb_delete(t, "x") == -1, "delete on empty tree should be -1");
	CHECK(rb_validate(t) == 0, "empty tree should validate");
	CHECK(rb_size(t) == 0, "empty tree size should be 0");
	rb_destroy(t); /* also exercises rb_destroy on an empty tree */
	rb_destroy(NULL); /* NULL-safe per contract */

	rbtree_t *t2 = rb_create(NULL);
	rb_insert(t2, "only", NULL);
	CHECK(rb_validate(t2) == 0, "single-node tree should validate");
	CHECK(rb_delete(t2, "only") == 0, "deleting the only node should succeed");
	CHECK(rb_size(t2) == 0, "size should be 0 after deleting the only node");
	CHECK(rb_validate(t2) == 0, "tree should validate after emptying");
	rb_destroy(t2);
}

/* --- larger randomized stress, insert/delete/find cross-checked --- */
#define N 2000
static void test_stress(void)
{
	printf("== stress: %d-key universe, 500000 ops ==\n", N);
	rbtree_t *t = rb_create(NULL);
	static int present[N];
	static char keys[N][16];
	for (int i = 0; i < N; i++) snprintf(keys[i], sizeof keys[i], "s%04d", i);

	srand(999);
	for (long iter = 0; iter < 500000; iter++) {
		int i = rand() % N;
		if (!present[i]) {
			if (rb_insert(t, keys[i], keys[i]) != 0) { printf("FAIL: insert(%s) rejected\n", keys[i]); check_failed = 1; return; }
			present[i] = 1;
		} else {
			if (rb_delete(t, keys[i]) != 0) { printf("FAIL: delete(%s) rejected but present\n", keys[i]); check_failed = 1; return; }
			present[i] = 0;
		}
		if (iter % 200 == 0 && rb_validate(t) != 0) {
			printf("FAIL: rb_validate failed at op %ld\n", iter); check_failed = 1; return;
		}
	}
	size_t expect = 0;
	for (int i = 0; i < N; i++) expect += present[i];
	CHECK(rb_size(t) == expect, "final size mismatch vs model");
	for (int i = 0; i < N; i++) {
		void *v = rb_find(t, keys[i]);
		if (present[i] && v == NULL) { printf("FAIL: %s missing\n", keys[i]); check_failed = 1; }
		if (!present[i] && v != NULL) { printf("FAIL: %s ghost\n", keys[i]); check_failed = 1; }
	}
	CHECK(rb_validate(t) == 0, "final validate");
	rb_destroy(t);
	printf("  stress done\n");
}

int main(void)
{
	test_foreach();
	test_overwrite();
	test_edges();
	test_stress();
	if (!check_failed) printf("\nALL DEBUG CHECKS PASSED (except the documented overwrite gap)\n");
	return 0;
