static struct rb_node *node_alloc(const char *key, void *value)
{
	struct rb_node *n = malloc(sizeof *n);
	if (n == NULL)
		goto fail_node;

	size_t klen = strlen(key) + 1;
	n->key = malloc(klen);
	if (n->key == NULL)
		goto fail_key;
	memcpy(n->key, key, klen);

	n->value  = value;
	n->left   = NULL;
	n->right  = NULL;
	n->parent = NULL;
	n->color  = RED;
	return n;

fail_key:
	free(n);
fail_node:
	return NULL;
}

